export const LIBRARY_BOOKS = Object.freeze(
  Object.fromEntries(
    Object.entries(RAW_BOOKS).map(([id, book]) => [Number(id), normalizeBook(book)]),
  ),
);
export const LIBRARY_BOOK_IDS = Object.freeze(Object.keys(LIBRARY_BOOKS).map(Number));

export function getLibraryBook(bookId) {
  return LIBRARY_BOOKS[Number(bookId)] ?? { author: "", pages: [] };
}
